-- ----------------------------
-- Table structure for chatgpt_chat_history
-- ----------------------------
DROP TABLE IF EXISTS `chatgpt_chat_history`;
CREATE TABLE `chatgpt_chat_history`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT '用户 ID',
  `chat_id` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '会话 ID',
  `type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '类型：prompt|reply',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '角色图标',
  `role_id` int(11) NOT NULL COMMENT '角色 ID',
  `model` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型名称',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '聊天内容',
  `tokens` smallint(6) NOT NULL COMMENT '耗费 token 数量',
  `total_tokens` int(11) NOT NULL COMMENT '消耗总Token长度',
  `use_context` tinyint(1) NOT NULL COMMENT '是否允许作为上下文语料',
  `created_at` datetime(0) NULL,
  `updated_at` datetime(0) NULL,
  `deleted_at` datetime(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `chat_id`(`chat_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 98 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '聊天历史记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of chatgpt_chat_history
-- ----------------------------
INSERT INTO `chatgpt_chat_history` VALUES (1, 4, '84c7db67-e81a-43be-84bd-06ffc064d401', 'prompt', 'http://localhost:5678/static/upload/2024/5/1715651569509929.png', 1, 'gpt-4o-mini', '用小学生都能听懂的术语解释什么是量子纠缠', 313, 313, 1, '2025-09-19 13:34:11', '2025-09-19 13:34:11', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (2, 4, '84c7db67-e81a-43be-84bd-06ffc064d401', 'reply', '/images/avatar/gpt.png', 1, 'gpt-4o-mini', '量子纠缠是一种很特别的现象，就像是有两个小朋友，他们之间有一种神奇的连接。\n\n想象一下，有两个小朋友在不同的地方，但不管他们离得多远，只要其中一个小朋友做了什么，比如说他开心了，另一个小朋友也会立刻知道，就算他们相隔很远，甚至在两个不同的城市。这种神奇的连接，就是量子纠缠。\n\n在量子世界里，一些小粒子（比如电子）可以通过这种方式紧紧连接在一起，彼此之间的状态是相互依赖的。这听起来可能有点奇怪，但科学家们已经在实验中证明了这种现象的存在。\n\n所以，量子纠缠就是小粒子之间的一种神奇的联系，让它们即使分开也能相互影响。就好像两个好朋友，无论距离多远，心里一直有着连结。', 313, 339, 1, '2025-09-19 13:34:14', '2025-09-19 13:34:14', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (3, 4, '84c7db67-e81a-43be-84bd-06ffc064d401', 'prompt', 'http://localhost:5678/static/upload/2024/5/1715651569509929.png', 1, 'gpt-4o-mini', '你知道目前有啥好的项目能做的吗？', 644, 644, 1, '2025-09-19 13:36:42', '2025-09-19 13:36:42', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (4, 4, '84c7db67-e81a-43be-84bd-06ffc064d401', 'reply', '/images/avatar/gpt.png', 1, 'gpt-4o-mini', '当然！目前有许多好的项目可以考虑，具体取决于你的兴趣和目标。这里有一些建议，适合不同领域和目的的项目：\n\n1. **环保项目**：\n   - **社区清理活动**：组织志愿者一起清理公园、海滩或街道，提升社区环境。\n   - **回收利用**：创建一个回收计划，鼓励人们减少塑料使用和增加可回收物品的利用。\n\n2. **科技项目**：\n   - **编程学习小组**：组织一个学习编程的团队，可以分享知识，互相帮助。\n   - **APP开发**：开发一款有趣或实用的手机应用，解决某个具体问题。\n\n3. **艺术与文化项目**：\n   - **社区艺术展**：邀请当地艺术家展示他们的作品，提升文化氛围。\n   - **书籍交换活动**：组织书籍交换活动，让大家互相分享喜欢的书。\n\n4. **教育项目**：\n   - **辅导班**：为需要帮助的同学提供免费的辅导，帮助他们提高学习成绩。\n   - **在线课程**：创建一个关于你擅长的主题的在线课程，分享给希望学习的人。\n\n5. **健康与健身项目**：\n   - **健身挑战**：发起一个社区健身挑战，鼓励大家一起锻炼，保持健康。\n   - **营养讲座**：举办营养知识讲座，帮助人们建立健康饮食习惯。\n\n6. **社会服务项目**：\n   - **志愿服务**：参与或组织志愿者活动，帮助社区中的弱势群体。\n   - **老人关怀**：走访社区中的老人，和他们聊天，了解他们的需求。\n\n选择一个你感兴趣的项目，并考虑你的时间、资源和人员支持，能让你的项目更成功！', 644, 1001, 1, '2025-09-19 13:36:44', '2025-09-19 13:36:44', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (5, 4, '8f12040a-51a2-477e-ad46-af1057be19cb', 'prompt', 'http://localhost:5678/static/upload/2024/5/1715651569509929.png', 1, 'advanced-voice', 'hello，', 7644, 7644, 1, '2025-09-19 13:37:30', '2025-09-19 13:37:30', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (6, 4, '8f12040a-51a2-477e-ad46-af1057be19cb', 'reply', '/images/avatar/gpt.png', 1, 'advanced-voice', '#### 💡小提示\n\n1. 请在20秒内点击进行通话，否则你的提示词可能会失效 \n2. 通话期间请勿刷新界面，否则链接将会失效\n3. 如果想要切换音色请以`breeze` `cove` `ember` `fathom` `glimmer` `harp` `juniper` `maple` `orbit` `reef` `ridge`开头\n例如：`orbit 请以中文和我进行对话`\n\n---\n\n[🎤点击进行语音通话](https://meet.artif.show/custom?liveKitUrl=wss://webrtc.artif.show&token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..PA7U4ZUONx0140ROY2PUT-XztxrOM2F7qQ4hvx0b3_8#MrajJ4f7dJxTVuJQpdzXP6)', 7644, 7646, 1, '2025-09-19 13:37:36', '2025-09-19 13:37:36', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (7, 4, 'ee0a85f0-b67b-44c8-a8fb-5643bf99625c', 'prompt', 'http://localhost:5678/static/upload/2024/5/1715651569509929.png', 1, 'gpt-4o-mini', '你好啊', 18, 18, 1, '2025-09-19 13:56:05', '2025-09-19 13:56:05', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (8, 4, 'ee0a85f0-b67b-44c8-a8fb-5643bf99625c', 'reply', '/images/avatar/gpt.png', 1, 'gpt-4o-mini', '你好！有什么我可以帮助你的吗？', 18, 22, 1, '2025-09-19 13:56:08', '2025-09-19 13:56:08', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (9, 4, 'a3a3a025-5984-4972-ae3a-dc7eb34fbad2', 'prompt', 'http://localhost:5678/static/upload/2024/5/1715651569509929.png', 1, 'gpt-4o-mini', '微博热搜', 191, 191, 1, '2025-09-19 13:57:14', '2025-09-19 13:57:14', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (10, 4, 'a3a3a025-5984-4972-ae3a-dc7eb34fbad2', 'reply', '/images/avatar/gpt.png', 1, 'gpt-4o-mini', '截至我最后的更新日期，我无法实时访问互联网或社交媒体平台，因此无法提供当前的微博热搜榜单。不过，通常微博热搜榜会涉及到最新的娱乐新闻、明星动态、热门事件、社会话题等。如果你想知道具体的热搜内容，建议直接访问微博或使用相关的新闻平台进行查询。你对微博的具体话题或趋势有兴趣吗？我可以提供一些常见的讨论方向或热门话题的背景信息。', 191, 199, 1, '2025-09-19 13:57:15', '2025-09-19 13:57:15', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (11, 4, 'bd7b4767-0017-4fd4-8da0-e665adc7beaf', 'prompt', 'http://localhost:5678/static/upload/2024/5/1715651569509929.png', 1, 'gpt-4o-mini', '今日早报', 579, 579, 1, '2025-09-19 13:58:23', '2025-09-19 13:58:23', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (12, 4, 'bd7b4767-0017-4fd4-8da0-e665adc7beaf', 'reply', '/images/avatar/gpt.png', 1, 'gpt-4o-mini', '当然可以！下面是一些可能在今天的早报中会出现的头条新闻内容：\n\n1. **国际动态**：\n   - 全球主要国家首脑会议在XXX举行，各国领导人就气候变化、经济复苏等议题进行了深入讨论。\n   - 地缘政治局势紧张，某国家与邻国之间的冲突升级，引发国际社会关注。\n\n2. **国内新闻**：\n   - 政府发布最新经济数据，显示经济增长势头良好，失业率进一步下降。\n   - 全国范围内的大规模疫苗接种活动启动，目标是在未来几个月内提高疫苗覆盖率。\n\n3. **科技与创新**：\n   - 某大型科技公司发布了新一代智能手机，搭载最新的AI技术，受到消费者热议。\n   - 科学家在可再生能源技术上取得重要突破，提升了太阳能电池的效率。\n\n4. **体育赛事**：\n   - 本届城市马拉松比赛圆满结束，来自全国的选手争相角逐，创下多项新纪录。\n   - 某国的足球联赛进入白热化阶段，各队争夺冠军的竞争愈发激烈。\n\n5. **文化娱乐**：\n   - 新上映的电影在全国范围内受到热烈反响，票房连创新高。\n   - 音乐节日再次回归，知名乐队和歌手将在本周末同台献艺。\n\n以上只是一个可能的早报示例，具体内容会根据实时新闻动态而有所不同。如需特定领域或话题的详细信息，请告诉我！', 579, 584, 1, '2025-09-19 13:58:24', '2025-09-19 13:58:24', NULL);
