INSERT INTO `chatgpt_chat_history` VALUES (15, 48, '38631af9-c78b-4275-acf0-fb3873744ab0', 'prompt', '/images/avatar/user.png', 1, 'gpt-4o-mini', '你知道什么是天马行空嘛？', 114, 114, 1, '2025-09-19 14:18:55', '2025-09-19 14:18:55', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (16, 48, '38631af9-c78b-4275-acf0-fb3873744ab0', 'reply', '/images/avatar/gpt.png', 1, 'gpt-4o-mini', '“天马行空”是一个成语，原指天马在空中自由奔跑，形容思维活动的自由、不受限制，常用来形容人的想象力丰富、思维开阔。有时也可以用于形容不切实际的想法或创意。你对这个成语有什么具体的疑问或想法吗？', 114, 152, 1, '2025-09-19 14:18:59', '2025-09-19 14:18:59', NULL);
INSERT INTO `chatgpt_chat_history` VALUES (17, 48, 'a265b93d-accb-45cc-8c9a-4f0ec156c584', 'prompt', '/images/avatar/user.png', 134, 'gpt-4o-mini', '你好啊', 20, 20, 1, '2025-09-19 14:19:30', '2025-09-19 14:19:30', NULL);
