-- ----------------------------
-- Table structure for chatgpt_products
-- ----------------------------
DROP TABLE IF EXISTS `chatgpt_products`;
CREATE TABLE `chatgpt_products`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '名称',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '价格',
  `discount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额',
  `days` smallint(6) NOT NULL DEFAULT 0 COMMENT '延长天数',
  `power` int(11) NOT NULL DEFAULT 0 COMMENT '增加算力值',
  `enabled` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否启动',
  `sales` int(11) NOT NULL DEFAULT 0 COMMENT '销量',
  `sort_num` tinyint(4) NOT NULL DEFAULT 0 COMMENT '排序',
  `created_at` datetime(0) NULL,
  `updated_at` datetime(0) NULL,
  `app_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'App跳转地址',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '跳转地址',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '会员套餐表' ROW_FORMAT = Dynamic;

